Lemma rpres_write : forall (C : Z -> Prop) m0 m a bs,
  rpres_except C m0 m -> 0 <= a -> a + Z.of_nat (length bs) <= 2^64 ->
  (forall x, a <= x < a + Z.of_nat (length bs) -> C x) ->
